INSERT INTO public.auto_error (error_type, error_code, error_name, error_desc, noti_running_process, noti_campaign,
INSERT INTO public.auto_outcome_signal_rules (platform, action_code, phase, signal_kind, pattern, priority, error_code, source, note) VALUES
  ('zalo', NULL, 'before_send', 'engine', '*', 10, 'err_network_offline', 'v500_review', '[Q5] Lỗi chưa gửi chưa có luật riêng (lỗi mạng, HTTP, hết giờ của thao tác đọc…): chưa gửi gì, xử lý như mất mạng (NET01).'),
  ('zalo', NULL, 'in_flight', 'engine', '*', 10, 'err_engine_unknown_delivery', 'v500_review', '[Q3] Lỗi khi đang gửi chưa có luật riêng (đứt mạng sau khi kết nối, hết giờ chờ…): không rõ đã tới, không gửi lại (UNK01).'),
  ('zalo', NULL, NULL, 'zalo_code', '-69', 10, 'err_engine_unknown_delivery', 'v500_review', '[Q3] Zalo trả -69 "Stop retry": không xác nhận được tin đã tới, không gửi lại (UNK01).'),
  ('zalo', NULL, NULL, 'message_like', 'Chưa có session Zalo%', 10, 'err_zalo_session_invalid', 'v500_review', '[Q4] Desktop chưa có phiên Zalo của tài khoản: như hết phiên (Z600).'),
  ('zalo', NULL, NULL, 'engine', 'target_missing_identity', 10, 'err_input_invalid', 'v500_review', '[Q1] Data thiếu/sai SĐT, UID, ID nhóm, link (app tự phát hiện): lỗi dữ liệu DAT01, không mượn mã Zalo 114.'),
  ('zalo', 'zalo_message_friend', NULL, 'zalo_code', '120', 10, 'err_zalo_120_message_stranger', 'v500_review', '[Q4] Nhắn bạn bè gặp 120: tài khoản bị hạn chế nhắn người lạ (người nhận không còn là bạn).'),
  ('zalo', 'zalo_message_friend', NULL, 'zalo_code', '802', 10, 'err_zalo_802_message_stranger', 'v500_review', '[Q4] Như 120 với mã 802.'),
  ('zalo', 'zalo_add_group_member', NULL, 'zalo_code', '164', 10, 'err_engine_zalo_not_group_member', 'v500_review', '[Q8] Thêm thành viên: tài khoản không ở trong nhóm.'),
  ('zalo', 'zalo_add_group_member', NULL, 'zalo_code', '183', 10, 'err_engine_zalo_group_member_limit', 'v500_review', '[Q8] Thêm thành viên: nhóm đủ số tối đa.'),
  ('zalo', 'zalo_join_group_link', NULL, 'zalo_code', '172', 10, 'err_engine_zalo_group_full', 'v500_review', '[Q8] Vào nhóm bằng link: nhóm đầy.'),
  ('zalo', 'zalo_join_group_link', NULL, 'zalo_code', '299', 10, 'err_engine_zalo_join_group_day_limit', 'v500_review', '[Q8] Vào nhóm bằng link: quá số nhóm trong ngày.'),
  ('zalo', 'zalo_cancel_sent_friend_request', NULL, 'zalo_code', '301', 10, 'err_engine_zalo_cancel_friend_day_limit', 'v500_review', '[Q8] Huỷ lời mời: quá số lần trong ngày.'),
  ('zalo', 'zalo_tag_contact', NULL, 'zalo_code', '230', 10, 'err_engine_zalo_tag_outdated', 'v500_review', '[Q8] Gắn tag: danh sách nhãn đã đổi (Outdated input).'),
  ('zalo', 'zalo_add_group_member', NULL, 'zalo_code', '240', 10, 'err_engine_zalo_group_invite_pending', 'v500_review', '[Q8] Thêm thành viên: chờ duyệt.');
